import { Component, input, computed, ChangeDetectionStrategy } from '@angular/core';
import { CommonModule, CurrencyPipe, PercentPipe, DecimalPipe } from '@angular/common';
import { Tramite } from '../../../../../models/tramite';
import { TramiteAnexoEmpleo, TramiteNivel } from '../../../../../models/tramite-anexo-empleo';
import { TramiteAnexoInversion } from '../../../../../models/tramite-anexo-inversion';
import { TramiteAnexoDiversidadContratacion } from '../../../../../models/tramite-anexo-diversidad-contratacion';

interface TotalesEmpleos {
  empleosExistentes: number;
  empleosNuevos: number;
  totalEmpleos: number;
  porcentajeAumentoEmpleos: number;
  sueldoPromedioExistente: number;
  sueldoPromedioNuevo: number;
  porcentajeAumentoSueldo: number;
  sueldoTotalMensual: number;
}

interface MonedaGrupo {
  moneda: string;
  registros: TramiteAnexoEmpleo[];
  totales: TotalesEmpleos;
}

interface NivelGrupo {
  nivel: string;
  nivelLabel: string;
  monedas: MonedaGrupo[];
  totales: TotalesEmpleos;
}

interface TotalesInversion {
  montoActual: number;
  montoFuturo: number;
  montoTotal: number;
  porcentajeActual: number;
  porcentajeFuturo: number;
}

interface MonedaGrupoInv {
  moneda: string;
  registros: TramiteAnexoInversion[];
  totales: TotalesInversion;
}

interface TipoGrupoInv {
  tipo: string;
  tipoLabel: string;
  monedas: MonedaGrupoInv[];
  totales: TotalesInversion;
}

const NIVEL_LABELS: Record<TramiteNivel, string> = {
  DIRECCION: 'Dirección',
  ADMINISTRACION: 'Administración',
  SUPERVISION: 'Supervisión',
  PRODUCCION: 'Producción',
  OTRO: 'Otro'
};

const NIVEL_ORDER: TramiteNivel[] = ['DIRECCION', 'ADMINISTRACION', 'SUPERVISION', 'PRODUCCION', 'OTRO'];

const TIPO_INVERSION_LABELS: Record<string, string> = {
  FIJA: 'Fija',
  DIFERIDA: 'Diferida',
  CAPITAL_TRABAJO: 'Capital de Trabajo',
  OTROS: 'Otros'
};

const TIPO_INVERSION_ORDER = ['FIJA', 'DIFERIDA', 'CAPITAL_TRABAJO', 'OTROS'];

@Component({
  selector: 'app-tramite-anexos',
  standalone: true,
  imports: [CommonModule, CurrencyPipe, PercentPipe, DecimalPipe],
  templateUrl: './tramite-anexos.html',
  styleUrl: './tramite-anexos.css',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class TramiteAnexos {
  tramite = input<Tramite | null>(null);

  anexo1TieneDatos = computed(() => (this.tramite()?.anexos_empleos?.length ?? 0) > 0);
  anexo2TieneDatos = computed(() => !!this.tramite()?.anexo_empleo_indirecto?.id);
  anexo3TieneDatos = computed(() => !!this.tramite()?.anexo_estudiante?.id);
  anexo4TieneDatos = computed(() => !!this.tramite()?.anexo_diversidad?.id);
  anexo5TieneDatos = computed(() => !!this.tramite()?.anexo_nivel_salarial?.id);
  anexo6TieneDatos = computed(() => (this.tramite()?.anexos_inversiones?.length ?? 0) > 0);
  anexo7TieneDatos = computed(() => !!this.tramite()?.anexo_origen_inversion?.id);
  anexo8TieneDatos = computed(() => (this.tramite()?.anexos_inversion_tecnologia?.length ?? 0) > 0);
  anexo9TieneDatos = computed(() => (this.tramite()?.anexos_proveeduria?.length ?? 0) > 0);
  anexo10TieneDatos = computed(() => !!this.tramite()?.anexo_proveeduria_entidad_federativa?.id);
  anexo11TieneDatos = computed(() => !!this.tramite()?.anexo_mercados?.id);
  anexo12TieneDatos = computed(() => !!this.tramite()?.anexo_prestaciones?.id);
  anexo13TieneDatos = computed(() => !!this.tramite()?.anexo_fuentes_energia?.id);

  esFueraCabecera = computed(() => this.tramite()?.proyecto_inversion?.fuera_cabecera_municipal ?? false);
  anexo14Documento = computed(() => 
    this.tramite()?.tramite_documentos?.find(d => d.seccion === 'proyecto-inversion-cabecera')
  );

  anexo14NoAplica = computed(() => !this.esFueraCabecera());
  anexo14TieneDocumento = computed(() => this.esFueraCabecera() && !!this.anexo14Documento());
  anexo14FaltaDocumento = computed(() => this.esFueraCabecera() && !this.anexo14Documento());

  anexosPorNivel = computed(() => this.agruparPorNivel());
  anexosInversionesPorTipo = computed(() => this.agruparInversionesPorTipo());

  private crearTotalesEmpleosVacios(): TotalesEmpleos {
    return {
      empleosExistentes: 0,
      empleosNuevos: 0,
      totalEmpleos: 0,
      porcentajeAumentoEmpleos: 0,
      sueldoPromedioExistente: 0,
      sueldoPromedioNuevo: 0,
      porcentajeAumentoSueldo: 0,
      sueldoTotalMensual: 0
    };
  }

  private crearTotalesInversionVacios(): TotalesInversion {
    return {
      montoActual: 0,
      montoFuturo: 0,
      montoTotal: 0,
      porcentajeActual: 0,
      porcentajeFuturo: 0
    };
  }

  private agruparPorNivel(): NivelGrupo[] {
    const anexos = this.tramite()?.anexos_empleos ?? [];
    const grupos = new Map<string, NivelGrupo>();

    for (const nivel of NIVEL_ORDER) {
      grupos.set(nivel, {
        nivel,
        nivelLabel: NIVEL_LABELS[nivel],
        monedas: [],
        totales: this.crearTotalesEmpleosVacios()
      });
    }

    const anexosPorNivel = new Map<string, TramiteAnexoEmpleo[]>();
    for (const anexo of anexos) {
      const nivel = anexo.nivel;
      if (!anexosPorNivel.has(nivel)) {
        anexosPorNivel.set(nivel, []);
      }
      anexosPorNivel.get(nivel)!.push(anexo);
    }

    for (const [nivel, registrosNivel] of anexosPorNivel) {
      const grupo = grupos.get(nivel);
      if (!grupo) continue;

      const monedasMap = new Map<string, TramiteAnexoEmpleo[]>();
      for (const registro of registrosNivel) {
        if (!monedasMap.has(registro.moneda)) {
          monedasMap.set(registro.moneda, []);
        }
        monedasMap.get(registro.moneda)!.push(registro);
      }

      for (const [moneda, registrosMoneda] of monedasMap) {
        grupo.monedas.push({
          moneda,
          registros: registrosMoneda,
          totales: this.calcularTotalesEmpleos(registrosMoneda)
        });
      }

      grupo.totales = this.calcularTotalesEmpleos(registrosNivel);
    }

    return Array.from(grupos.values());
  }

  private agruparInversionesPorTipo(): TipoGrupoInv[] {
    const anexos = this.tramite()?.anexos_inversiones ?? [];
    const grupos = new Map<string, TipoGrupoInv>();

    for (const tipo of TIPO_INVERSION_ORDER) {
      grupos.set(tipo, {
        tipo,
        tipoLabel: TIPO_INVERSION_LABELS[tipo],
        monedas: [],
        totales: this.crearTotalesInversionVacios()
      });
    }

    const anexosPorTipo = new Map<string, TramiteAnexoInversion[]>();
    for (const anexo of anexos) {
      const tipo = anexo.tipo_inversion;
      if (!anexosPorTipo.has(tipo)) {
        anexosPorTipo.set(tipo, []);
      }
      anexosPorTipo.get(tipo)!.push(anexo);
    }

    const totalGeneralMonto = this.calcularTotalGeneralMontoInversion();

    for (const [tipo, registrosTipo] of anexosPorTipo) {
      const grupo = grupos.get(tipo);
      if (!grupo) continue;

      const monedasMap = new Map<string, TramiteAnexoInversion[]>();
      for (const registro of registrosTipo) {
        if (!monedasMap.has(registro.moneda)) {
          monedasMap.set(registro.moneda, []);
        }
        monedasMap.get(registro.moneda)!.push(registro);
      }

      for (const [moneda, registrosMoneda] of monedasMap) {
        grupo.monedas.push({
          moneda,
          registros: registrosMoneda,
          totales: this.calcularTotalesInversion(registrosMoneda, totalGeneralMonto)
        });
      }

      grupo.totales = this.calcularTotalesInversion(registrosTipo, totalGeneralMonto);
    }

    return Array.from(grupos.values());
  }

  private calcularTotalGeneralMontoInversion(): number {
    const anexos = this.tramite()?.anexos_inversiones ?? [];
    return anexos.reduce((sum, r) => sum + (+(r.cantidad_futura || 0) - +(r.cantidad_actual || 0)), 0);
  }

  private calcularTotalesEmpleos(registros: TramiteAnexoEmpleo[]): TotalesEmpleos {
    if (registros.length === 0) {
      return this.crearTotalesEmpleosVacios();
    }

    const empleosExistentes = registros.reduce((sum, r) => sum + +(r.empleos_existentes || 0), 0);
    const empleosNuevos = registros.reduce((sum, r) => sum + +(r.empleos_nuevos || 0), 0);
    const totalEmpleos = empleosExistentes + empleosNuevos;

    const sueldoDiarioExistente = registros.reduce((sum, r) => sum + (+(r.empleos_existentes || 0) * +(r.sueldo_promedio_diario_existente || 0)), 0);
    const sueldoDiarioNuevo = registros.reduce((sum, r) => sum + (+(r.empleos_nuevos || 0) * +(r.sueldo_promedio_diario_nuevo || 0)), 0);

    const sueldoPromedioExistente = empleosExistentes > 0
      ? sueldoDiarioExistente / empleosExistentes
      : 0;

    const sueldoPromedioNuevo = empleosNuevos > 0
      ? sueldoDiarioNuevo / empleosNuevos
      : 0;

    const porcentajeAumentoEmpleos = empleosExistentes > 0 ? (empleosNuevos / empleosExistentes) * 100 : 0;

    const porcentajeAumentoSueldo = sueldoPromedioExistente > 0
      ? ((sueldoPromedioNuevo - sueldoPromedioExistente) / sueldoPromedioExistente) * 100
      : 0;

    const sueldoTotalMensual = (sueldoDiarioExistente + sueldoDiarioNuevo) * 30;

    return {
      empleosExistentes,
      empleosNuevos,
      totalEmpleos,
      porcentajeAumentoEmpleos,
      sueldoPromedioExistente,
      sueldoPromedioNuevo,
      porcentajeAumentoSueldo,
      sueldoTotalMensual
    };
  }

  private calcularTotalesInversion(registros: TramiteAnexoInversion[], totalGeneralMonto: number): TotalesInversion {
    if (registros.length === 0) {
      return this.crearTotalesInversionVacios();
    }

    const montoActual = registros.reduce((sum, r) => sum + +(r.cantidad_actual || 0), 0);
    const montoFuturo = registros.reduce((sum, r) => sum + +(r.cantidad_futura || 0), 0);
    const montoTotal = montoFuturo - montoActual;

    const porcentajeActual = totalGeneralMonto > 0 ? (montoActual / totalGeneralMonto) * 100 : 0;
    const porcentajeFuturo = totalGeneralMonto > 0 ? (montoFuturo / totalGeneralMonto) * 100 : 0;

    return {
      montoActual,
      montoFuturo,
      montoTotal,
      porcentajeActual,
      porcentajeFuturo
    };
  }

  getTotalEmpleos(registro: TramiteAnexoEmpleo): number {
    return (registro.empleos_existentes || 0) + +(registro.empleos_nuevos || 0);
  }

  getPorcentajeAumentoEmpleos(registro: TramiteAnexoEmpleo): number {
    if (!registro.empleos_existentes || registro.empleos_existentes === 0) return 0;
    return (registro.empleos_nuevos / registro.empleos_existentes) * 100;
  }

  getPorcentajeAumentoSueldo(registro: TramiteAnexoEmpleo): number {
    if (!registro.sueldo_promedio_diario_existente || registro.sueldo_promedio_diario_existente === 0) return 0;
    if (!registro.sueldo_promedio_diario_nuevo) return 0;
    return ((registro.sueldo_promedio_diario_nuevo - registro.sueldo_promedio_diario_existente) / registro.sueldo_promedio_diario_existente) * 100;
  }

  getSueldoTotalMensual(registro: TramiteAnexoEmpleo): number {
    const totalEmpleos = this.getTotalEmpleos(registro);
    const sueldoPromedio = registro.sueldo_promedio_diario_nuevo || registro.sueldo_promedio_diario_existente || 0;
    return totalEmpleos * sueldoPromedio * 30;
  }

  getNivelLabel(nivel: string): string {
    return NIVEL_LABELS[nivel as TramiteNivel] || nivel;
  }

  getNivelColor(nivel: string): string {
    const colores: Record<string, string> = {
      DIRECCION: 'primary',
      ADMINISTRACION: 'success',
      SUPERVISION: 'info',
      PRODUCCION: 'warning',
      OTRO: 'secondary'
    };
    return colores[nivel] || 'secondary';
  }

  getTipoInversionLabel(tipo: string): string {
    return TIPO_INVERSION_LABELS[tipo] || tipo;
  }

  getTipoInversionColor(tipo: string): string {
    const colores: Record<string, string> = {
      FIJA: 'primary',
      DIFERIDA: 'success',
      CAPITAL_TRABAJO: 'info',
      OTROS: 'secondary'
    };
    return colores[tipo] || 'secondary';
  }

  getTotalInversion(registro: TramiteAnexoInversion): number {
    return (registro.cantidad_futura || 0) - (registro.cantidad_actual || 0);
  }

  getPorcentajeActual(registro: TramiteAnexoInversion): number {
    const totalGeneral = this.calcularTotalGeneralMontoInversion();
    if (totalGeneral === 0) return 0;
    return ((registro.cantidad_actual || 0) / totalGeneral) * 100;
  }

  getPorcentajeFuturo(registro: TramiteAnexoInversion): number {
    const totalGeneral = this.calcularTotalGeneralMontoInversion();
    if (totalGeneral === 0) return 0;
    return ((registro.cantidad_futura || 0) / totalGeneral) * 100;
  }

  calcularPorcentajeAhorro(consumoTotal: number | null, consumoPosterior: number | null): number | null {
    if (!consumoTotal || !consumoPosterior || consumoTotal <= 0) {
      return null;
    }
    return ((consumoTotal - consumoPosterior) / consumoTotal) * 100;
  }

  calcularPorcentajeDiversidad(anexo: TramiteAnexoDiversidadContratacion | undefined): number | null {
    if (!anexo) return null;
    const total = (anexo.num_personas_mayores || 0) + +(anexo.num_madres_solteras || 0) + +(anexo.num_personas_capacidades_diferentes || 0) + +(anexo.num_egresados_albergues || 0);
    if (total === 0) return null;
    return anexo.porcentaje_que_representan ?? null;
  }

  getTotalInversionTecnologia(): number {
    const anexos = this.tramite()?.anexos_inversion_tecnologia ?? [];
    return anexos.reduce((sum, r) => sum + +(r.monto || 0), 0);
  }

  getTotalProveeduria(): number {
    const anexos = this.tramite()?.anexos_proveeduria ?? [];
    return anexos.reduce((sum, r) => sum + +(r.valor_adquisicion || 0), 0);
  }
}
