import { Component, EventEmitter, inject, Input, Output } from '@angular/core';
import { Tramite, TramiteStatus } from '../../../../models/tramite';
import { TramiteService } from '../../../../controllers/tramite.service';

@Component({
  selector: 'app-tramites-acciones',
  imports: [],
  templateUrl: './tramites-acciones.html',
  styleUrl: './tramites-acciones.css',
})
export class TramitesAcciones {
  @Input() tramite ?: Tramite
  @Output() tramiteChange = new EventEmitter<Tramite>()

  private tramiteService = inject(TramiteService);

  async cambiarStatus(status: TramiteStatus){
    if(!this.tramite){
      return;
    }
    const res = await this.tramiteService.updateTramiteStatus(this.tramite?.id, status)

    if(!res){
      return;
    }

    this.tramite.status=status
    this.tramiteChange.emit(this.tramite)
  }
}
